alter table public.family_groups add column if not exists max_members integer not null default 5;
create table if not exists public.location_submissions (id uuid primary key default gen_random_uuid(), location_id uuid references public.locations(id) on delete set null, submitted_by uuid not null references auth.users(id) on delete cascade, payload jsonb not null default '{}'::jsonb, status text not null default 'pending_review' check(status in ('pending_review','accepted','needs_correction','rejected','claimed')), claimed_business_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.location_claims (id uuid primary key default gen_random_uuid(), location_id uuid not null references public.locations(id) on delete cascade, business_id uuid not null, claimed_by uuid not null references auth.users(id) on delete cascade, status text not null default 'pending' check(status in ('pending','approved','rejected')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(location_id,business_id));
create table if not exists public.ad_placements (id uuid primary key default gen_random_uuid(), placement_code text unique not null, surface text not null, slot text not null, active boolean not null default true, eligible_tiers text[] not null default array['free']);
insert into public.pricing_catalog(code,name,category,price_cents,interval,max_users,max_locations,price_note,features,active) values ('premium','Premium','consumer',500,'month',1,null,'$5/month','["advanced_amenity_search","premium_maps","no_ads"]',true),('family','Family Premium','consumer',2000,'month',5,null,'$20/month for up to 5 people','["all_premium_features","up_to_5_members","no_ads"]',true) on conflict(code) do update set name=excluded.name,price_cents=excluded.price_cents,interval=excluded.interval,max_users=excluded.max_users,price_note=excluded.price_note,features=excluded.features,active=true;
insert into public.ad_placements(placement_code,surface,slot,eligible_tiers) values ('home_after_quick_play','home','after_quick_play',array['free']),('maps_between_results','maps','between_results',array['free']),('community_feed','social','feed',array['free']) on conflict(placement_code) do update set active=true;
create or replace function public.family_has_premium_access(p_user_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.family_members fm join public.family_groups fg on fg.id=fm.group_id where fm.user_id=p_user_id and fg.max_members <= 5); $$;
create or replace function public.get_effective_consumer_tier(p_user_id uuid) returns text language sql stable security definer set search_path=public as $$ select case when public.family_has_premium_access(p_user_id) then 'premium' else coalesce((select subscription_tier::text from public.profiles where id=p_user_id),'free') end; $$;
create index if not exists idx_location_submissions_status on public.location_submissions(status);
create index if not exists idx_location_claims_location on public.location_claims(location_id);
